'use strict';

var emojiModifierBase = require('unicode-emoji-modifier-base');

var skinTones = new Map([['none', ''], ['white', '🏻'], ['creamWhite', '🏼'], ['lightBrown', '🏽'], ['brown', '🏾'], ['darkBrown', '🏿']]);

module.exports = function (emoji, tone) {
  if (!skinTones.has(tone)) {
    throw new TypeError("Unexpected `skinTone` name: ".concat(tone));
  }

  emoji = emoji.replace(/(?:\uD83C[\uDFFB-\uDFFF])/, '');

  if (emojiModifierBase.has(emoji.codePointAt(0)) && tone !== 'none') {
    emoji += skinTones.get(tone);
  }

  return emoji;
};